scan_table_check.script:
(function(engine, current) {
    var context = new global.EcsContext(current);
    if (context.value('description').replace(/\s+/g, '')) {
        return;
    }
    var report = new global.EcsReport(engine, {
        ruleId: 'SN-SI-003',
        title: 'Script Include without a description',
        recommendation: 'Describe what the Script Include is for, who calls it (server, client, other applications) ' +
            'and any important side effects, so reviewers and maintainers can tell without reading the code.',
        current: current
    });
    report.addRecord('Script Include "' + context.value('name') + '" has no description.');
    engine.finding.setCurrentSource(current);
    report.flush();
})(engine, current);
